from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        return neighbors

    forward = {start: [start]}
    backward = {goal: [goal]}
    visited_forward = {start}
    visited_backward = {goal}
    forward_queue = deque([start])
    backward_queue = deque([goal])

    while forward_queue and backward_queue:
        # Expand forward direction
        if len(forward_queue) <= len(backward_queue):
            current = forward_queue.popleft()
            for neighbor in get_neighbors(current[0], current[1]):
                if neighbor not in visited_forward:
                    visited_forward.add(neighbor)
                    forward[neighbor] = forward[current] + [neighbor]
                    forward_queue.append(neighbor)
                    if neighbor in backward:
                        path = forward[neighbor] + backward[neighbor][::-1]
                        return path
        else:
            current = backward_queue.popleft()
            for neighbor in get_neighbors(current[0], current[1]):
                if neighbor not in visited_backward:
                    visited_backward.add(neighbor)
                    backward[neighbor] = backward[current] + [neighbor]
                    backward_queue.append(neighbor)
                    if neighbor in forward:
                        path = forward[neighbor] + backward[neighbor][::-1]
                        return path

    return []

