    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    heap = [(0, start[0], start[1])]
    came_from = {}

    while heap:
        dist, r, c = heapq.heappop(heap)
        if (r, c) == goal:
