def solve(n, edges, s, t):
    if s == t:
        return 0

    # Initialize distance array with infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # SPFA (Shortest Path Faster Algorithm)
    in_queue = [False] * n
    queue = [s]
    in_queue[s] = True
    cnt = [0] * n  # Count of times node is relaxed

    while queue:
        u = queue.pop(0)
        in_queue[u] = False
        cnt[u] += 1

        if cnt[u] > n:
            # Detected a negative cycle, but since all weights are non-negative, this shouldn't happen
            return -1

        for u_v, v, w in edges:
            if u_v == u:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    if not in_queue[v]:
                        queue.append(v)
                        in_queue[v] = True

    return dist[t] if dist[t] != float('inf') else -1

