import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list for original and reversed graph
    adj = [[] for _ in range(n)]
    rev_adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        rev_adj[v].append((u, w))

    # Dijkstra's algorithm
    def dijkstra(start, adj, n):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist

    # Bidirectional Dijkstra
    dist_s = dijkstra(s, adj, n)
    dist_t = dijkstra(t, rev_adj, n)

    # Check if t is reachable from s
    if dist_s[t] == float('inf'):
        return -1

    # Find the shortest path by meeting in the middle
    # We'll run Dijkstra from s and t until the shortest path is found
    # or until the frontiers meet
    # Use a priority queue for each search

    # Priority queue for forward search from s
    forward = [(0, s)]
    # Priority queue for backward search from t
    backward = [(0, t)]
    # Visited for forward search
    visited_forward = {s: 0}
    # Visited for backward search
    visited_backward = {t: 0}
    # To track the distance from s and t respectively
    dist_from_s = {s: 0}
    dist_from_t = {t: 0}

    while forward and backward:
        # Process forward direction
        d1, u1 = heapq.heappop(forward)
        if u1 in visited_backward:
            return d1 + visited_backward[u1]
        if u1 not in visited_forward or d1 < visited_forward[u1]:
            visited_forward[u1] = d1
            for v, w in adj[u1]:
                if v not in visited_forward or d1 + w < visited_forward[v]:
                    heapq.heappush(forward, (d1 + w, v))
                    dist_from_s[v] = d1 + w

        # Process backward direction
        d2, u2 = heapq.heappop(backward)
        if u2 in visited_forward:
            return d2 + visited_forward[u2]
        if u2 not in visited_backward or d2 < visited_backward[u2]:
            visited_backward[u2] = d2
            for v, w in rev_adj[u2]:
                if v not in visited_backward or d2 + w < visited_backward[v]:
                    heapq.heappush(backward, (d2 + w, v))
                    dist_from_t[v] = d2 + w

    # If no meeting point found
    return -1

