def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Bucket queue: list of lists, index is distance, value is list of nodes
    buckets = [[] for _ in range(n * 100 + 1)]  # max possible distance is 100 * 100
    buckets[0].append(s)

    # Process buckets in order of increasing distance
    while buckets[0]:
        # Get the first bucket with nodes
        for d in range(len(buckets)):
            if buckets[d]:
                break
        else:
            break  # no more nodes to process

        # Process all nodes in current bucket
        for u in buckets[d]:
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    # Move v from its old bucket to new one
                    if buckets[dist[v]]:
                        buckets[dist[v]].remove(v)
                    buckets[dist[v]].append(v)
        # Clear current bucket
        buckets[d].clear()

    return dist[t] if dist[t] != INF else -1

