    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Initialize distances to infinity
    import math
    INF = math.inf
    dist = [INF] * n
    dist[s] = 0

    # Bucket queue: index is distance, value is list of nodes at that distance
    bucket = {}
    for i in range(n):
        bucket[i] = []

    # Initialize bucket with starting node
    bucket[0].append(s)

    # Process buckets in increasing order of distance
    while bucket:
        # Find the smallest distance with non-empty bucket
        for d in range(n):
            if bucket[d]:
                break
        else:
            break  # No more nodes to process

        # Get all nodes at distance d
        nodes = bucket[d]
        del bucket[d]  # Remove the bucket

        for u in nodes:
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
